<?php require_once 'functions.php'; if(logged_in()){header('Location: index.php');exit;} $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';
if($name===''||$username===''||$email===''||$password==='')$errors[]='Please complete every field.'; if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.'; if(strlen($password)<8)$errors[]='Password must be at least 8 characters.';
if(!$errors){try{$st=$pdo->prepare('INSERT INTO users(full_name,username,email,password_hash) VALUES(?,?,?,?)');$st->execute([$name,$username,$email,password_hash($password,PASSWORD_DEFAULT)]);flash('Account created. You can now log in.');header('Location: login.php');exit;}catch(PDOException $e){$errors[]='That username or email is already registered.';}}}
page_header('Create account'); ?> <div class="auth-wrap"><form class="panel auth-panel" method="post"><p class="eyebrow">JOIN THE COMMUNITY</p><h1>Create account</h1><p class="muted">Create an account to post reports and submit claims.</p><?php foreach($errors as $error): ?><div class="alert error"><?=e($error)?></div><?php endforeach; ?><label>Full name<input name="full_name" required maxlength="120" value="<?=e($_POST['full_name']??'')?>"></label><label>Username<input name="username" required maxlength="50" value="<?=e($_POST['username']??'')?>"></label><label>Email address<input type="email" name="email" required value="<?=e($_POST['email']??'')?>"></label><label>Password<input type="password" name="password" minlength="8" required></label><button class="button full" type="submit">Create account</button><p class="form-foot">Already registered? <a href="login.php">Log in</a></p></form></div><?php page_footer(); ?>
